/* GERADO POR scripts/gerar-repo.mjs — NÃO EDITAR À MÃO.
   Corre `npm run gerar-repo` depois de mexer em laboratorio/. */

export const FICHEIROS: Record<string, string> = {
  "src/balcao/api/__init__.py": "\"\"\"API HTTP do «Balcão» (FastAPI): conversas com streaming por SSE, aprovações, pesquisa, ingestão e avaliação.\"\"\"\n\nfrom balcao.api.app import create_app\n\n__all__ = [\"create_app\"]\n",
  "src/balcao/api/app.py": "\"\"\"A aplicação FastAPI do «Balcão»: `create_app()` e o ciclo de vida dos recursos (adr-0001).\n\nO `lifespan` monta tudo uma vez por processo — modelos, índice, cadeia, grafo,\npools de ligações — e fecha-o por ordem inversa ao terminar. Nenhum pedido\npaga o custo de criar um cliente HTTP ou uma ligação à base de dados.\n\nCom `DATABASE_URL`: índice no pgvector, checkpoints no PostgreSQL\n(`AsyncPostgresSaver`, adr-0014) e conversas nas tabelas do esquema. Sem ela:\ntudo em memória, com o corpus ingerido no arranque — o modo dos testes.\n\nUso: `uvicorn balcao.api.app:create_app --factory --host 0.0.0.0 --port 8000`.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport logging\nfrom collections.abc import AsyncIterator\nfrom contextlib import AsyncExitStack, asynccontextmanager\nfrom dataclasses import dataclass, field\nfrom typing import Any\n\nfrom fastapi import FastAPI, Request\nfrom fastapi.exceptions import RequestValidationError\nfrom fastapi.middleware.cors import CORSMiddleware\nfrom fastapi.responses import JSONResponse\nfrom langgraph.checkpoint.memory import InMemorySaver\nfrom starlette.concurrency import run_in_threadpool\nfrom starlette.exceptions import HTTPException as StarletteHTTPException\n\nfrom balcao import observabilidade\nfrom balcao.api.esquemas import EstadoIngestao, Problema\nfrom balcao.api.repositorio import Repositorio, RepositorioMemoria, RepositorioPostgres\nfrom balcao.api.rotas import ErroProblema, router\nfrom balcao.config import Configuracao, obter_config\nfrom balcao.grafo import Sistema, montar_sistema\nfrom balcao.modelos import escalao_de, nome_modelo\n\n__all__ = [\"Servicos\", \"create_app\"]\n\nlog = logging.getLogger(__name__)\n\n\n@dataclass\nclass Servicos:\n    \"\"\"O que as rotas usam. Vive em `app.state.servicos` durante a vida do processo.\"\"\"\n\n    cfg: Configuracao\n    sistema: Sistema\n    grafo: Any\n    repo: Repositorio\n    callbacks: list[Any]\n    nome_modelo: str\n    ingestoes: dict[str, EstadoIngestao] = field(default_factory=dict)\n\n\n@asynccontextmanager\nasync def _ciclo_de_vida(app: FastAPI) -> AsyncIterator[None]:\n    cfg: Configuracao = app.state.cfg\n    observabilidade.configurar(\"balcao\", cfg.versao, consola=cfg.otel_consola)\n    async with AsyncExitStack() as pilha:\n        # Montar o sistema faz I/O síncrono (pool do índice, ingestão em memória).\n        sistema = await run_in_threadpool(montar_sistema, cfg)\n        repo: Repositorio\n        if cfg.usa_postgres:\n            from langgraph.checkpoint.postgres.aio import AsyncPostgresSaver\n            from psycopg.rows import dict_row\n            from psycopg_pool import AsyncConnectionPool\n\n            # O checkpointer quer autocommit e sem prepared statements (compatível com PgBouncer).\n            pool = AsyncConnectionPool(\n                cfg.conninfo,\n                min_size=cfg.pool_min,\n                max_size=cfg.pool_max,\n                open=False,\n                name=\"balcao-checkpoints\",\n                kwargs={\"autocommit\": True, \"prepare_threshold\": 0, \"row_factory\": dict_row},\n            )\n            await pool.open()\n            pilha.push_async_callback(pool.close)\n            checkpointer: Any = AsyncPostgresSaver(pool)  # type: ignore[arg-type]\n            await checkpointer.setup()  # cria as tabelas de checkpoints se não existirem\n            repo_pg = RepositorioPostgres(cfg.conninfo, cfg.pool_min, cfg.pool_max)\n            pilha.callback(repo_pg.fechar)\n            fechar_indice = getattr(sistema.indice, \"fechar\", None)\n            if callable(fechar_indice):\n                pilha.callback(fechar_indice)\n            repo = repo_pg\n        else:\n            checkpointer = InMemorySaver()\n            repo = RepositorioMemoria()\n\n        escaloes = {nome_modelo(cfg, p): escalao_de(p, cfg.modelo_fornecedor) for p in (\"classificar\", \"responder\")}\n        app.state.servicos = Servicos(\n            cfg=cfg,\n            sistema=sistema,\n            grafo=sistema.compilar(checkpointer),\n            repo=repo,\n            callbacks=[observabilidade.CallbackObservabilidade(cfg.modelo_fornecedor, escaloes)],\n            nome_modelo=nome_modelo(cfg, \"responder\"),\n        )\n        log.info(\"balcão pronto: fornecedor=%s, postgres=%s\", cfg.modelo_fornecedor, cfg.usa_postgres)\n        yield\n\n\ndef _problema(status: int, title: str, detail: str | None, request: Request, tipo: str = \"about:blank\") -> JSONResponse:\n    corpo = Problema(type=tipo, title=title, status=status, detail=detail, instance=str(request.url.path))\n    return JSONResponse(corpo.model_dump(exclude_none=True), status_code=status, media_type=\"application/problem+json\")\n\n\ndef create_app(cfg: Configuracao | None = None) -> FastAPI:\n    \"\"\"Fábrica da aplicação. Nos testes passa-se uma `Configuracao` explícita.\"\"\"\n    cfg = cfg or obter_config()\n    app = FastAPI(\n        title=\"Balcão\",\n        summary=\"Assistente de suporte ao cliente do Chega\",\n        version=cfg.versao,\n        lifespan=_ciclo_de_vida,\n    )\n    app.state.cfg = cfg\n    if cfg.cors_origens:\n        app.add_middleware(\n            CORSMiddleware,\n            allow_origins=cfg.cors_origens,\n            allow_methods=[\"GET\", \"POST\"],\n            allow_headers=[\"Authorization\", \"Content-Type\"],\n        )\n\n    @app.exception_handler(ErroProblema)\n    async def _erro_problema(request: Request, exc: ErroProblema) -> JSONResponse:\n        return _problema(exc.status_code, exc.title, exc.detail, request, exc.tipo)\n\n    @app.exception_handler(RequestValidationError)\n    async def _erro_validacao(request: Request, exc: RequestValidationError) -> JSONResponse:\n        campos = \"; \".join(f\"{'.'.join(str(p) for p in e['loc'])}: {e['msg']}\" for e in exc.errors())\n        return _problema(422, \"Pedido inválido\", campos, request)\n\n    @app.exception_handler(StarletteHTTPException)\n    async def _erro_http(request: Request, exc: StarletteHTTPException) -> JSONResponse:\n        return _problema(exc.status_code, str(exc.detail), None, request)\n\n    @app.exception_handler(Exception)\n    async def _erro_interno(request: Request, exc: Exception) -> JSONResponse:\n        log.exception(\"erro não tratado em %s\", request.url.path)\n        return _problema(500, \"Erro interno\", None, request)\n\n    app.include_router(router)\n    return app\n",
  "src/balcao/api/esquemas.py": "\"\"\"Esquemas Pydantic da API: o contrato HTTP do «Balcão».\n\nTudo o que entra é validado aqui (tamanhos máximos incluídos: uma mensagem de\n50 000 caracteres é um ataque ao orçamento de tokens, não uma pergunta). Tudo o\nque sai tem um modelo, para que o OpenAPI gerado em `/docs` seja o contrato.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom datetime import datetime\nfrom typing import Any, Literal\n\nfrom pydantic import BaseModel, ConfigDict, Field\n\n__all__ = [\n    \"Aprovacao\",\n    \"Conversa\",\n    \"ConversaDetalhe\",\n    \"CriarConversa\",\n    \"Decisao\",\n    \"DocumentoEntrada\",\n    \"EnviarMensagem\",\n    \"EstadoAvaliacao\",\n    \"EstadoIngestao\",\n    \"Feedback\",\n    \"FeedbackRegistado\",\n    \"Mensagem\",\n    \"PedidoAvaliacao\",\n    \"PedidoIngestao\",\n    \"PedidoPesquisa\",\n    \"Problema\",\n    \"ResultadoDecisao\",\n    \"ResultadoPesquisa\",\n    \"Saude\",\n]\n\nCanal = Literal[\"app\", \"whatsapp\"]\n\n\nclass _Base(BaseModel):\n    model_config = ConfigDict(extra=\"forbid\", str_strip_whitespace=True)\n\n\n# ------------------------------------------------------------------ conversas\n\n\nclass CriarConversa(_Base):\n    canal: Canal = \"app\"\n\n\nclass Conversa(BaseModel):\n    id: str\n    cliente_id: str\n    canal: Canal\n    estado: Literal[\"aberta\", \"a_aguardar_aprovacao\", \"escalada\", \"fechada\"] = \"aberta\"\n    criada_em: datetime\n\n\nclass EnviarMensagem(_Base):\n    texto: str = Field(min_length=1, max_length=2000, examples=[\"O meu pedido PD-8842507 ainda vai demorar muito?\"])\n\n\nclass Mensagem(BaseModel):\n    id: str\n    conversa_id: str\n    papel: Literal[\"cliente\", \"assistente\"]\n    texto: str\n    \"\"\"Já mascarado: a API nunca guarda nem devolve dados pessoais em claro (RNF-04).\"\"\"\n    citacoes: list[str] = Field(default_factory=list)\n    intencao: str | None = None\n    criada_em: datetime\n    meta: dict[str, Any] = Field(default_factory=dict)\n\n\nclass ConversaDetalhe(Conversa):\n    mensagens: list[Mensagem]\n    aprovacao_pendente: str | None = None\n\n\nclass Feedback(_Base):\n    mensagem_id: str\n    util: bool\n    comentario: str | None = Field(default=None, max_length=500)\n\n\nclass FeedbackRegistado(BaseModel):\n    id: str\n    mensagem_id: str\n    util: bool\n\n\n# ------------------------------------------------------------------ pesquisa\n\n\nclass PedidoPesquisa(_Base):\n    consulta: str = Field(min_length=2, max_length=300)\n    k: int = Field(default=4, ge=1, le=20)\n    incluir_internos: bool = Field(default=False, description=\"Só para o papel operador.\")\n\n\nclass ResultadoPesquisa(BaseModel):\n    documento_id: str\n    chunk_id: str\n    titulo: str\n    texto: str\n    publico: str\n    score: float\n    score_rrf: float\n\n\n# ------------------------------------------------------------------ ingestão\n\n\nclass DocumentoEntrada(_Base):\n    id: str = Field(pattern=r\"^[a-z0-9]+(-[a-z0-9]+)+$\", max_length=80)\n    titulo: str = Field(max_length=200)\n    categoria: str = Field(max_length=60)\n    publico: Literal[\"cliente\", \"interno\"]\n    vigente: bool = True\n    actualizado: str = Field(pattern=r\"^\\d{4}-\\d{2}-\\d{2}$\")\n    texto: str = Field(min_length=10, max_length=50_000)\n\n\nclass PedidoIngestao(_Base):\n    documentos: list[DocumentoEntrada] = Field(default_factory=list, max_length=500)\n    incluir_corpus: bool = False\n\n\nclass EstadoIngestao(BaseModel):\n    id: str\n    estado: Literal[\"pendente\", \"a_correr\", \"concluida\", \"falhou\"]\n    criada_em: datetime\n    relatorio: dict[str, Any] | None = None\n    erro: str | None = None\n\n\n# ----------------------------------------------------------------- aprovações\n\n\nclass Aprovacao(BaseModel):\n    id: str\n    conversa_id: str\n    cliente_id: str\n    pedido_id: str\n    valor_mzn: int\n    motivo: str\n    estado: Literal[\"pendente\", \"aprovada\", \"recusada\"]\n    criada_em: datetime\n    decidida_em: datetime | None = None\n    revisor: str | None = None\n    nota: str | None = None\n\n\nclass Decisao(_Base):\n    aprovado: bool\n    nota: str | None = Field(default=None, max_length=500)\n\n\nclass ResultadoDecisao(BaseModel):\n    aprovacao: Aprovacao\n    mensagem: Mensagem\n\n\n# ----------------------------------------------------------------- avaliação\n\n\nclass PedidoAvaliacao(_Base):\n    conjunto: Literal[\"dourado\", \"redteam\", \"todos\"] = \"dourado\"\n    limite: int | None = Field(default=None, ge=1, le=1000)\n\n\nclass EstadoAvaliacao(BaseModel):\n    id: str\n    estado: Literal[\"pendente\", \"a_correr\", \"concluida\", \"falhou\"]\n    conjunto: str\n    criada_em: datetime\n    metricas: dict[str, Any] | None = None\n    gate_ok: bool | None = None\n    erro: str | None = None\n\n\n# -------------------------------------------------------------------- outros\n\n\nclass Saude(BaseModel):\n    estado: Literal[\"ok\", \"degradado\"]\n    versao: str\n    fornecedor: str\n    detalhes: dict[str, Any] = Field(default_factory=dict)\n\n\nclass Problema(BaseModel):\n    \"\"\"RFC 9457 (Problem Details for HTTP APIs), servido como `application/problem+json`.\"\"\"\n\n    type: str = \"about:blank\"\n    title: str\n    status: int\n    detail: str | None = None\n    instance: str | None = None\n",
  "src/balcao/api/repositorio.py": "\"\"\"Persistência da API: conversas, mensagens, feedback, aprovações e corridas de avaliação.\n\nDuas implementações com a mesma interface: em memória (testes e laboratório\nsem base de dados) e PostgreSQL (tabelas de `sql/001_esquema.sql`). O estado\ndo grafo não vive aqui — vive nos checkpoints do LangGraph; isto é a vista do\nproduto e da equipa de suporte, com os textos já mascarados.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport threading\nimport uuid\nfrom datetime import UTC, datetime\nfrom typing import Any, Protocol\n\nfrom balcao.api.esquemas import Aprovacao, Conversa, EstadoAvaliacao, FeedbackRegistado, Mensagem\n\n__all__ = [\"Repositorio\", \"RepositorioMemoria\", \"RepositorioPostgres\", \"novo_id\"]\n\n\ndef novo_id(prefixo: str) -> str:\n    return f\"{prefixo}-{uuid.uuid4().hex[:12]}\"\n\n\ndef _agora() -> datetime:\n    return datetime.now(UTC)\n\n\nclass Repositorio(Protocol):\n    def criar_conversa(self, cliente_id: str, canal: str) -> Conversa: ...\n    def obter_conversa(self, conversa_id: str) -> Conversa | None: ...\n    def mudar_estado_conversa(self, conversa_id: str, estado: str) -> None: ...\n    def adicionar_mensagem(\n        self,\n        conversa_id: str,\n        papel: str,\n        texto: str,\n        citacoes: list[str] | None = None,\n        intencao: str | None = None,\n        meta: dict[str, Any] | None = None,\n    ) -> Mensagem: ...\n    def listar_mensagens(self, conversa_id: str) -> list[Mensagem]: ...\n    def registar_feedback(\n        self, conversa_id: str, mensagem_id: str, util: bool, comentario: str | None\n    ) -> FeedbackRegistado: ...\n    def registar_aprovacao(self, ap: Aprovacao) -> Aprovacao: ...\n    def obter_aprovacao(self, aprovacao_id: str) -> Aprovacao | None: ...\n    def listar_aprovacoes(self, estado: str | None = None) -> list[Aprovacao]: ...\n    def decidir_aprovacao(self, aprovacao_id: str, aprovado: bool, revisor: str, nota: str | None) -> Aprovacao: ...\n    def guardar_avaliacao(\n        self, av: EstadoAvaliacao, versao_prompt: str | None = None, modelo: str | None = None\n    ) -> None: ...\n    def obter_avaliacao(self, avaliacao_id: str) -> EstadoAvaliacao | None: ...\n    def pronto(self) -> bool: ...\n\n\n# ===================================================================== memória\n\n\nclass RepositorioMemoria:\n    \"\"\"Dicionários com um trinco. Chega para um processo; não sobrevive a um reinício.\"\"\"\n\n    def __init__(self) -> None:\n        self._conversas: dict[str, Conversa] = {}\n        self._mensagens: dict[str, list[Mensagem]] = {}\n        self._feedback: dict[str, FeedbackRegistado] = {}\n        self._aprovacoes: dict[str, Aprovacao] = {}\n        self._avaliacoes: dict[str, EstadoAvaliacao] = {}\n        self._trinco = threading.Lock()\n\n    def criar_conversa(self, cliente_id: str, canal: str) -> Conversa:\n        c = Conversa(id=novo_id(\"CV\"), cliente_id=cliente_id, canal=canal, criada_em=_agora())\n        with self._trinco:\n            self._conversas[c.id] = c\n            self._mensagens[c.id] = []\n        return c\n\n    def obter_conversa(self, conversa_id: str) -> Conversa | None:\n        return self._conversas.get(conversa_id)\n\n    def mudar_estado_conversa(self, conversa_id: str, estado: str) -> None:\n        with self._trinco:\n            c = self._conversas[conversa_id]\n            self._conversas[conversa_id] = c.model_copy(update={\"estado\": estado})\n\n    def adicionar_mensagem(\n        self,\n        conversa_id: str,\n        papel: str,\n        texto: str,\n        citacoes: list[str] | None = None,\n        intencao: str | None = None,\n        meta: dict[str, Any] | None = None,\n    ) -> Mensagem:\n        m = Mensagem(\n            id=novo_id(\"MS\"),\n            conversa_id=conversa_id,\n            papel=papel,\n            texto=texto,\n            citacoes=citacoes or [],\n            intencao=intencao,\n            criada_em=_agora(),\n            meta=meta or {},\n        )\n        with self._trinco:\n            self._mensagens.setdefault(conversa_id, []).append(m)\n        return m\n\n    def listar_mensagens(self, conversa_id: str) -> list[Mensagem]:\n        return list(self._mensagens.get(conversa_id, []))\n\n    def registar_feedback(\n        self, conversa_id: str, mensagem_id: str, util: bool, comentario: str | None\n    ) -> FeedbackRegistado:\n        if not any(m.id == mensagem_id for m in self._mensagens.get(conversa_id, [])):\n            raise KeyError(mensagem_id)\n        f = FeedbackRegistado(id=novo_id(\"FB\"), mensagem_id=mensagem_id, util=util)\n        with self._trinco:\n            self._feedback[mensagem_id] = f\n        return f\n\n    def registar_aprovacao(self, ap: Aprovacao) -> Aprovacao:\n        with self._trinco:\n            return self._aprovacoes.setdefault(ap.id, ap)\n\n    def obter_aprovacao(self, aprovacao_id: str) -> Aprovacao | None:\n        return self._aprovacoes.get(aprovacao_id)\n\n    def listar_aprovacoes(self, estado: str | None = None) -> list[Aprovacao]:\n        return sorted(\n            (a for a in self._aprovacoes.values() if estado is None or a.estado == estado), key=lambda a: a.criada_em\n        )\n\n    def decidir_aprovacao(self, aprovacao_id: str, aprovado: bool, revisor: str, nota: str | None) -> Aprovacao:\n        with self._trinco:\n            ap = self._aprovacoes[aprovacao_id]\n            novo = ap.model_copy(\n                update={\n                    \"estado\": \"aprovada\" if aprovado else \"recusada\",\n                    \"revisor\": revisor,\n                    \"nota\": nota,\n                    \"decidida_em\": _agora(),\n                }\n            )\n            self._aprovacoes[aprovacao_id] = novo\n            return novo\n\n    def guardar_avaliacao(\n        self, av: EstadoAvaliacao, versao_prompt: str | None = None, modelo: str | None = None\n    ) -> None:\n        with self._trinco:\n            self._avaliacoes[av.id] = av\n\n    def obter_avaliacao(self, avaliacao_id: str) -> EstadoAvaliacao | None:\n        return self._avaliacoes.get(avaliacao_id)\n\n    def pronto(self) -> bool:\n        return True\n\n\n# ================================================================ PostgreSQL\n\n\nclass RepositorioPostgres:\n    \"\"\"As mesmas operações sobre as tabelas do esquema, com um pool de ligações `psycopg`.\"\"\"\n\n    def __init__(self, conninfo: str, min_size: int = 1, max_size: int = 10) -> None:\n        from psycopg.rows import dict_row\n        from psycopg_pool import ConnectionPool\n\n        self.pool = ConnectionPool(\n            conninfo,\n            min_size=min_size,\n            max_size=max_size,\n            open=True,\n            kwargs={\"row_factory\": dict_row},\n            name=\"balcao-api\",\n        )\n\n    def fechar(self) -> None:\n        self.pool.close()\n\n    def _um(self, sql: str, params: dict[str, Any] | tuple[Any, ...]) -> dict[str, Any] | None:\n        with self.pool.connection() as con:\n            return con.execute(sql, params).fetchone()  # type: ignore[return-value]\n\n    def _todos(self, sql: str, params: dict[str, Any] | tuple[Any, ...]) -> list[dict[str, Any]]:\n        with self.pool.connection() as con:\n            return con.execute(sql, params).fetchall()  # type: ignore[return-value]\n\n    def criar_conversa(self, cliente_id: str, canal: str) -> Conversa:\n        linha = self._um(\n            \"INSERT INTO conversas (id, cliente_id, canal) VALUES (%s, %s, %s) RETURNING *\",\n            (novo_id(\"CV\"), cliente_id, canal),\n        )\n        return Conversa(**linha)  # type: ignore[arg-type]\n\n    def obter_conversa(self, conversa_id: str) -> Conversa | None:\n        linha = self._um(\"SELECT * FROM conversas WHERE id = %s\", (conversa_id,))\n        return Conversa(**linha) if linha else None\n\n    def mudar_estado_conversa(self, conversa_id: str, estado: str) -> None:\n        self._um(\"UPDATE conversas SET estado = %s WHERE id = %s RETURNING id\", (estado, conversa_id))\n\n    def adicionar_mensagem(\n        self,\n        conversa_id: str,\n        papel: str,\n        texto: str,\n        citacoes: list[str] | None = None,\n        intencao: str | None = None,\n        meta: dict[str, Any] | None = None,\n    ) -> Mensagem:\n        from psycopg.types.json import Jsonb\n\n        linha = self._um(\n            \"INSERT INTO mensagens (id, conversa_id, papel, texto, citacoes, intencao, meta) \"\n            \"VALUES (%s, %s, %s, %s, %s, %s, %s) RETURNING *\",\n            (novo_id(\"MS\"), conversa_id, papel, texto, citacoes or [], intencao, Jsonb(meta or {})),\n        )\n        return Mensagem(**linha)  # type: ignore[arg-type]\n\n    def listar_mensagens(self, conversa_id: str) -> list[Mensagem]:\n        return [\n            Mensagem(**ln)\n            for ln in self._todos(\n                \"SELECT * FROM mensagens WHERE conversa_id = %s ORDER BY criada_em, id\", (conversa_id,)\n            )\n        ]\n\n    def registar_feedback(\n        self, conversa_id: str, mensagem_id: str, util: bool, comentario: str | None\n    ) -> FeedbackRegistado:\n        linha = self._um(\n            \"INSERT INTO feedback (id, conversa_id, mensagem_id, util, comentario) \"\n            \"SELECT %s, %s, m.id, %s, %s FROM mensagens m WHERE m.id = %s AND m.conversa_id = %s \"\n            \"ON CONFLICT (mensagem_id) DO UPDATE SET util = EXCLUDED.util, comentario = EXCLUDED.comentario, \"\n            \"criado_em = now() RETURNING id, mensagem_id, util\",\n            (novo_id(\"FB\"), conversa_id, util, comentario, mensagem_id, conversa_id),\n        )\n        if linha is None:\n            raise KeyError(mensagem_id)\n        return FeedbackRegistado(**linha)\n\n    def registar_aprovacao(self, ap: Aprovacao) -> Aprovacao:\n        self._um(\n            \"INSERT INTO aprovacoes (id, conversa_id, cliente_id, pedido_id, valor_mzn, motivo, estado, criada_em) \"\n            \"VALUES (%(id)s, %(conversa_id)s, %(cliente_id)s, %(pedido_id)s, %(valor_mzn)s, %(motivo)s, \"\n            \"%(estado)s, %(criada_em)s) ON CONFLICT (id) DO NOTHING RETURNING id\",\n            ap.model_dump(),\n        )\n        return self.obter_aprovacao(ap.id) or ap\n\n    def obter_aprovacao(self, aprovacao_id: str) -> Aprovacao | None:\n        linha = self._um(\"SELECT * FROM aprovacoes WHERE id = %s\", (aprovacao_id,))\n        return Aprovacao(**linha) if linha else None\n\n    def listar_aprovacoes(self, estado: str | None = None) -> list[Aprovacao]:\n        if estado is None:\n            return [Aprovacao(**ln) for ln in self._todos(\"SELECT * FROM aprovacoes ORDER BY criada_em\", ())]\n        return [\n            Aprovacao(**ln)\n            for ln in self._todos(\"SELECT * FROM aprovacoes WHERE estado = %s ORDER BY criada_em\", (estado,))\n        ]\n\n    def decidir_aprovacao(self, aprovacao_id: str, aprovado: bool, revisor: str, nota: str | None) -> Aprovacao:\n        # `AND estado = 'pendente'`: duas decisões simultâneas não se sobrepõem.\n        linha = self._um(\n            \"UPDATE aprovacoes SET estado = %s, revisor = %s, nota = %s, decidida_em = now() \"\n            \"WHERE id = %s AND estado = 'pendente' RETURNING *\",\n            (\"aprovada\" if aprovado else \"recusada\", revisor, nota, aprovacao_id),\n        )\n        if linha is None:\n            raise KeyError(aprovacao_id)\n        return Aprovacao(**linha)\n\n    def guardar_avaliacao(\n        self, av: EstadoAvaliacao, versao_prompt: str | None = None, modelo: str | None = None\n    ) -> None:\n        from psycopg.types.json import Jsonb\n\n        self._um(\n            \"INSERT INTO corridas_avaliacao (id, conjunto, estado, versao_prompt, modelo, metricas, gate_ok, erro, \"\n            \"criada_em, terminada_em) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, \"\n            \"CASE WHEN %s IN ('concluida', 'falhou') THEN now() END) \"\n            \"ON CONFLICT (id) DO UPDATE SET estado = EXCLUDED.estado, metricas = EXCLUDED.metricas, \"\n            \"gate_ok = EXCLUDED.gate_ok, erro = EXCLUDED.erro, terminada_em = EXCLUDED.terminada_em RETURNING id\",\n            (\n                av.id,\n                av.conjunto,\n                av.estado,\n                versao_prompt,\n                modelo,\n                Jsonb(av.metricas) if av.metricas else None,\n                av.gate_ok,\n                av.erro,\n                av.criada_em,\n                av.estado,\n            ),\n        )\n\n    def obter_avaliacao(self, avaliacao_id: str) -> EstadoAvaliacao | None:\n        linha = self._um(\"SELECT * FROM corridas_avaliacao WHERE id = %s\", (avaliacao_id,))\n        if not linha:\n            return None\n        return EstadoAvaliacao(\n            id=linha[\"id\"],\n            estado=linha[\"estado\"],\n            conjunto=linha[\"conjunto\"],\n            criada_em=linha[\"criada_em\"],\n            metricas=linha[\"metricas\"],\n            gate_ok=linha[\"gate_ok\"],\n            erro=linha[\"erro\"],\n        )\n\n    def pronto(self) -> bool:\n        try:\n            return self._um(\"SELECT 1 AS ok\", ()) is not None\n        except Exception:\n            return False\n",
  "src/balcao/api/rotas.py": "\"\"\"Os endpoints do «Balcão».\n\nA rota que importa é `POST /v1/conversas/{id}/mensagens`: corre um turno do\ngrafo e devolve-o por Server-Sent Events (adr-0021), com os eventos\n\n* `token` — um pedaço do texto, à medida que o modelo gera (TTFT, RNF-01);\n* `ferramenta` — uma chamada de ferramenta e o seu resultado (sem os dados);\n* `citacao` — cada fonte validada pela guarda de saída;\n* `aprovacao` — o grafo parou num `interrupt` à espera de um humano;\n* `fim` — o texto final validado (que substitui o que foi mostrado, se a guarda\n  o alterou), a intenção e as citações;\n* `erro` — um Problem Details (RFC 9457); o stream fecha a seguir.\n\nAutenticação por bearer token com três papéis (cliente, supervisor, operador).\nNo laboratório, os tokens vêm de `BALCAO_TOKENS_API`; em produção seria um JWT\nvalidado localmente contra o IdP. O `cliente_id` sai do token e segue no\n`RunnableConfig` até às ferramentas — nunca do corpo do pedido.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nimport logging\nimport secrets\nimport time\nfrom collections.abc import AsyncIterator\nfrom dataclasses import dataclass\nfrom datetime import UTC, datetime\nfrom typing import Annotated, Any\n\nfrom fastapi import APIRouter, BackgroundTasks, Depends, Query, Request, Response, status\nfrom fastapi.responses import StreamingResponse\nfrom fastapi.security import HTTPAuthorizationCredentials, HTTPBearer\nfrom langchain_core.messages import AIMessage, AIMessageChunk, HumanMessage, ToolMessage\nfrom langchain_core.runnables import RunnableConfig\nfrom langgraph.types import Command\nfrom prometheus_client import CONTENT_TYPE_LATEST, generate_latest\nfrom starlette.concurrency import run_in_threadpool\n\nfrom balcao import observabilidade\nfrom balcao.api.esquemas import (\n    Aprovacao,\n    Conversa,\n    ConversaDetalhe,\n    CriarConversa,\n    Decisao,\n    EnviarMensagem,\n    EstadoAvaliacao,\n    EstadoIngestao,\n    Feedback,\n    FeedbackRegistado,\n    PedidoAvaliacao,\n    PedidoIngestao,\n    PedidoPesquisa,\n    ResultadoDecisao,\n    ResultadoPesquisa,\n    Saude,\n)\nfrom balcao.api.repositorio import novo_id\nfrom balcao.config import Papel\nfrom balcao.grafo import config_de_execucao\nfrom balcao.guardas import mascarar\nfrom balcao.ingestao import DocumentoFonte, carregar_corpus, ingerir\nfrom balcao.modelos import nome_embeddings\nfrom balcao.recuperacao import criar_recuperador\n\n__all__ = [\"ErroProblema\", \"Utilizador\", \"router\"]\n\nlog = logging.getLogger(__name__)\nrouter = APIRouter()\n_bearer = HTTPBearer(auto_error=False)\n\n# Nós cujas mensagens chegam ao cliente. As da guarda de saída não: essas\n# substituem uma mensagem já mostrada e chegam no evento `fim`.\n_NOS_VISIVEIS = {\"responder_rag\", \"agente\", \"escalar\", \"preparar_aprovacao\", \"aguardar_aprovacao\"}\n\n\nclass ErroProblema(Exception):\n    \"\"\"Erro que a API devolve como `application/problem+json` (RFC 9457).\"\"\"\n\n    def __init__(self, status_code: int, title: str, detail: str | None = None, tipo: str = \"about:blank\") -> None:\n        super().__init__(detail or title)\n        self.status_code, self.title, self.detail, self.tipo = status_code, title, detail, tipo\n\n\n# ================================================================ dependências\n\n\ndef servicos(request: Request) -> Any:\n    return request.app.state.servicos\n\n\n@dataclass(frozen=True)\nclass Utilizador:\n    papel: Papel\n    cliente_id: str | None\n    sujeito: str\n\n\ndef utilizador(\n    cred: Annotated[HTTPAuthorizationCredentials | None, Depends(_bearer)],\n    s: Annotated[Any, Depends(servicos)],\n) -> Utilizador:\n    if cred is None:\n        raise ErroProblema(401, \"Não autenticado\", \"Falta o cabeçalho Authorization: Bearer <token>.\")\n    # Comparação em tempo constante contra todos os tokens: não se revela qual quase acertou.\n    encontrado: str | None = None\n    for token, valor in s.cfg.tokens_api.items():\n        if secrets.compare_digest(token.encode(), cred.credentials.encode()):\n            encontrado = valor\n    if encontrado is None:\n        raise ErroProblema(401, \"Token inválido\")\n    papel, _, cliente = encontrado.partition(\":\")\n    if papel not in (\"cliente\", \"supervisor\", \"operador\"):\n        raise ErroProblema(500, \"Configuração de tokens inválida\")\n    if papel == \"cliente\" and not cliente:\n        raise ErroProblema(500, \"Token de cliente sem cliente_id\")\n    # O sujeito identifica quem decidiu (auditoria) sem guardar o token.\n    sujeito = cliente or hashlib.sha256(cred.credentials.encode()).hexdigest()[:8]\n    return Utilizador(papel=papel, cliente_id=cliente or None, sujeito=f\"{papel}:{sujeito}\")  # type: ignore[arg-type]\n\n\ndef exigir(*papeis: Papel) -> Any:\n    def _verificar(u: Annotated[Utilizador, Depends(utilizador)]) -> Utilizador:\n        if u.papel not in papeis:\n            raise ErroProblema(403, \"Sem permissão\", f\"Esta operação exige o papel {' ou '.join(papeis)}.\")\n        return u\n\n    return _verificar\n\n\ndef _conversa_acessivel(s: Any, conversa_id: str, u: Utilizador, so_dono: bool = False) -> Conversa:\n    c = s.repo.obter_conversa(conversa_id)\n    # 404 também para conversas alheias: não se confirma que existem.\n    if c is None or (u.papel == \"cliente\" and c.cliente_id != u.cliente_id) or (so_dono and u.papel != \"cliente\"):\n        raise ErroProblema(404, \"Conversa não encontrada\")\n    return c\n\n\ndef _sse(evento: str, dados: dict[str, Any]) -> str:\n    return f\"event: {evento}\\ndata: {json.dumps(dados, ensure_ascii=False, default=str)}\\n\\n\"\n\n\n# =================================================================== conversas\n\n\n@router.post(\"/v1/conversas\", status_code=status.HTTP_201_CREATED, response_model=Conversa, tags=[\"conversas\"])\ndef criar_conversa(\n    corpo: CriarConversa,\n    u: Annotated[Utilizador, Depends(exigir(\"cliente\"))],\n    s: Annotated[Any, Depends(servicos)],\n) -> Conversa:\n    \"\"\"Abre uma conversa para o cliente autenticado. O id é também o `thread_id` do grafo.\"\"\"\n    return s.repo.criar_conversa(str(u.cliente_id), corpo.canal)\n\n\n@router.post(\n    \"/v1/conversas/{conversa_id}/mensagens\", tags=[\"conversas\"], responses={200: {\"content\": {\"text/event-stream\": {}}}}\n)\nasync def enviar_mensagem(\n    conversa_id: str,\n    corpo: EnviarMensagem,\n    u: Annotated[Utilizador, Depends(exigir(\"cliente\"))],\n    s: Annotated[Any, Depends(servicos)],\n) -> StreamingResponse:\n    \"\"\"Um turno da conversa, devolvido por Server-Sent Events.\"\"\"\n    conversa = _conversa_acessivel(s, conversa_id, u, so_dono=True)\n    if conversa.estado == \"a_aguardar_aprovacao\":\n        raise ErroProblema(\n            409,\n            \"Conversa à espera de aprovação\",\n            \"Um colega está a rever um reembolso desta conversa; a resposta chega aqui.\",\n        )\n    texto_mascarado = mascarar(corpo.texto)\n    await run_in_threadpool(s.repo.adicionar_mensagem, conversa_id, \"cliente\", texto_mascarado)\n    cliente_id = str(u.cliente_id)\n    config = config_de_execucao(conversa_id, cliente_id, s.cfg, canal=conversa.canal)\n    config[\"callbacks\"] = s.callbacks\n    entrada = {\"messages\": [HumanMessage(corpo.texto)], \"cliente_id\": cliente_id}\n    return StreamingResponse(\n        _turno(s, conversa_id, entrada, config),\n        media_type=\"text/event-stream\",\n        headers={\"Cache-Control\": \"no-cache\", \"X-Accel-Buffering\": \"no\"},\n    )\n\n\nasync def _turno(s: Any, conversa_id: str, entrada: dict[str, Any], config: RunnableConfig) -> AsyncIterator[str]:\n    \"\"\"Corre o grafo e traduz os seus eventos em SSE.\"\"\"\n    t0 = time.perf_counter()\n    mostrado: list[str] = []\n    nos_com_tokens: set[str] = set()\n    rota = \"?\"\n    try:\n        async for modo, dados in s.grafo.astream(entrada, config, stream_mode=[\"messages\", \"updates\"]):\n            if modo == \"messages\":\n                msg, meta = dados\n                no = meta.get(\"langgraph_node\", \"\")\n                if no not in _NOS_VISIVEIS or not isinstance(msg, AIMessage | AIMessageChunk):\n                    continue\n                if isinstance(msg, AIMessageChunk):\n                    nos_com_tokens.add(no)\n                elif no in nos_com_tokens:\n                    continue  # a mensagem completa de um nó que já foi transmitido aos pedaços\n                if msg.text and not getattr(msg, \"tool_call_chunks\", None) and not getattr(msg, \"tool_calls\", None):\n                    if not mostrado:\n                        observabilidade.TTFT.labels(rota=no).observe(time.perf_counter() - t0)\n                    mostrado.append(msg.text)\n                    yield _sse(\"token\", {\"texto\": msg.text})\n            elif modo == \"updates\":\n                for no, act in dados.items():\n                    if no == \"__interrupt__\":\n                        for intr in act:\n                            ap = await _registar_aprovacao(s, conversa_id, intr.value)\n                            yield _sse(\"aprovacao\", ap.model_dump(mode=\"json\"))\n                    elif no == \"classificar\" and act:\n                        rota = str(act.get(\"intencao\", rota))\n                    elif no == \"agente\" and act:\n                        for m in act.get(\"messages\", []):\n                            for tc in getattr(m, \"tool_calls\", []) or []:\n                                yield _sse(\"ferramenta\", {\"nome\": tc[\"name\"], \"estado\": \"chamada\", \"id\": tc[\"id\"]})\n                    elif no == \"ferramentas\" and act:\n                        for m in act.get(\"messages\", []):\n                            if isinstance(m, ToolMessage):\n                                yield _sse(\n                                    \"ferramenta\",\n                                    {\n                                        \"nome\": m.name,\n                                        \"estado\": \"resultado\",\n                                        \"id\": m.tool_call_id,\n                                        \"erro\": m.status == \"error\" or '\"erro\"' in m.text,\n                                    },\n                                )\n\n        estado = (await s.grafo.aget_state(config)).values\n        final = next((m for m in reversed(estado.get(\"messages\", [])) if isinstance(m, AIMessage)), None)\n        texto = final.text if final else \"\"\n        if not mostrado and texto:\n            yield _sse(\"token\", {\"texto\": texto})\n        titulos = {c[\"id\"]: c.get(\"titulo\", \"\") for c in estado.get(\"contexto\", [])}\n        for cid in estado.get(\"citacoes\", []):\n            yield _sse(\"citacao\", {\"id\": cid, \"titulo\": titulos.get(cid, \"\")})\n        meta = {\n            \"rota\": estado.get(\"origem\"),\n            \"recusa\": estado.get(\"recusa\", False),\n            \"versao\": s.cfg.versao,\n            \"modelo\": s.nome_modelo,\n        }\n        msg = await run_in_threadpool(\n            s.repo.adicionar_mensagem,\n            conversa_id,\n            \"assistente\",\n            texto,\n            list(estado.get(\"citacoes\", [])),\n            estado.get(\"intencao\"),\n            meta,\n        )\n        if estado.get(\"origem\") == \"escalar\":\n            await run_in_threadpool(s.repo.mudar_estado_conversa, conversa_id, \"escalada\")\n        observabilidade.DURACAO.labels(rota=rota).observe(time.perf_counter() - t0)\n        yield _sse(\n            \"fim\",\n            {\n                \"mensagem_id\": msg.id,\n                \"texto\": texto,\n                \"substituir\": \"\".join(mostrado).strip() != texto.strip(),\n                \"intencao\": estado.get(\"intencao\"),\n                \"citacoes\": estado.get(\"citacoes\", []),\n                \"aprovacao_pendente\": (estado.get(\"aprovacao\") or {}).get(\"estado\") == \"pendente\",\n            },\n        )\n    except Exception as e:\n        log.exception(\"turno falhou na conversa %s\", conversa_id)\n        yield _sse(\n            \"erro\",\n            {\n                \"type\": \"about:blank\",\n                \"title\": \"Erro ao processar a mensagem\",\n                \"status\": 500,\n                \"detail\": type(e).__name__,\n                \"instance\": f\"/v1/conversas/{conversa_id}/mensagens\",\n            },\n        )\n\n\nasync def _registar_aprovacao(s: Any, conversa_id: str, valor: dict[str, Any]) -> Aprovacao:\n    ap = Aprovacao(\n        id=valor[\"id\"],\n        conversa_id=conversa_id,\n        cliente_id=valor[\"cliente_id\"],\n        pedido_id=valor[\"pedido_id\"],\n        valor_mzn=int(valor[\"valor_mzn\"]),\n        motivo=valor[\"motivo\"],\n        estado=\"pendente\",\n        criada_em=datetime.now(UTC),\n    )\n    ap = await run_in_threadpool(s.repo.registar_aprovacao, ap)\n    await run_in_threadpool(s.repo.mudar_estado_conversa, conversa_id, \"a_aguardar_aprovacao\")\n    return ap\n\n\n@router.get(\"/v1/conversas/{conversa_id}\", response_model=ConversaDetalhe, tags=[\"conversas\"])\ndef ler_conversa(\n    conversa_id: str,\n    u: Annotated[Utilizador, Depends(utilizador)],\n    s: Annotated[Any, Depends(servicos)],\n) -> ConversaDetalhe:\n    c = _conversa_acessivel(s, conversa_id, u)\n    pendente = next((a.id for a in s.repo.listar_aprovacoes(\"pendente\") if a.conversa_id == conversa_id), None)\n    return ConversaDetalhe(\n        **c.model_dump(), mensagens=s.repo.listar_mensagens(conversa_id), aprovacao_pendente=pendente\n    )\n\n\n@router.post(\n    \"/v1/conversas/{conversa_id}/feedback\", status_code=201, response_model=FeedbackRegistado, tags=[\"conversas\"]\n)\ndef enviar_feedback(\n    conversa_id: str,\n    corpo: Feedback,\n    u: Annotated[Utilizador, Depends(exigir(\"cliente\"))],\n    s: Annotated[Any, Depends(servicos)],\n) -> FeedbackRegistado:\n    _conversa_acessivel(s, conversa_id, u, so_dono=True)\n    try:\n        return s.repo.registar_feedback(\n            conversa_id, corpo.mensagem_id, corpo.util, mascarar(corpo.comentario) if corpo.comentario else None\n        )\n    except KeyError:\n        raise ErroProblema(404, \"Mensagem não encontrada nesta conversa\") from None\n\n\n# ==================================================================== pesquisa\n\n\n@router.post(\"/v1/pesquisa\", response_model=list[ResultadoPesquisa], tags=[\"conhecimento\"])\ndef pesquisar(\n    corpo: PedidoPesquisa,\n    u: Annotated[Utilizador, Depends(utilizador)],\n    s: Annotated[Any, Depends(servicos)],\n) -> list[ResultadoPesquisa]:\n    \"\"\"A mesma pesquisa híbrida que a cadeia usa. Documentos internos só para operadores.\"\"\"\n    if corpo.incluir_internos and u.papel != \"operador\":\n        raise ErroProblema(403, \"Sem permissão\", \"Só operadores pesquisam documentos internos.\")\n    publicos = (\"cliente\", \"interno\") if corpo.incluir_internos else (\"cliente\",)\n    rec = criar_recuperador(s.cfg, s.sistema.indice, s.sistema.embeddings, publicos)\n    return [\n        ResultadoPesquisa(\n            documento_id=d.metadata[\"documento_id\"],\n            chunk_id=str(d.metadata.get(\"chunk_id\", d.id)),\n            titulo=d.metadata.get(\"titulo\", \"\"),\n            texto=d.page_content,\n            publico=d.metadata.get(\"publico\", \"\"),\n            score=float(d.metadata.get(\"score\", sc)),\n            score_rrf=float(d.metadata.get(\"score_rrf\", 0.0)),\n        )\n        for d, sc in rec.pesquisar_com_scores(corpo.consulta, corpo.k)\n    ]\n\n\n# ==================================================================== ingestão\n\n\n@router.post(\"/v1/ingestao\", status_code=202, response_model=EstadoIngestao, tags=[\"conhecimento\"])\ndef criar_ingestao(\n    corpo: PedidoIngestao,\n    tarefas: BackgroundTasks,\n    _u: Annotated[Utilizador, Depends(exigir(\"operador\"))],\n    s: Annotated[Any, Depends(servicos)],\n) -> EstadoIngestao:\n    \"\"\"Aceita documentos e indexa-os em segundo plano, sem parar o serviço (RF-07).\"\"\"\n    if not corpo.documentos and not corpo.incluir_corpus:\n        raise ErroProblema(422, \"Nada para ingerir\", \"Envie documentos ou incluir_corpus=true.\")\n    est = EstadoIngestao(id=novo_id(\"IG\"), estado=\"pendente\", criada_em=datetime.now(UTC))\n    s.ingestoes[est.id] = est\n    docs = [DocumentoFonte(**d.model_dump(), fonte=\"api\") for d in corpo.documentos]\n    if corpo.incluir_corpus:\n        docs = carregar_corpus() + docs\n\n    def correr() -> None:\n        s.ingestoes[est.id] = est.model_copy(update={\"estado\": \"a_correr\"})\n        try:\n            rel = ingerir(docs, s.sistema.indice, s.cfg, nome_embeddings(s.cfg))\n            s.ingestoes[est.id] = est.model_copy(update={\"estado\": \"concluida\", \"relatorio\": rel.como_dict()})\n        except Exception as e:\n            log.exception(\"ingestão %s falhou\", est.id)\n            s.ingestoes[est.id] = est.model_copy(update={\"estado\": \"falhou\", \"erro\": type(e).__name__})\n\n    tarefas.add_task(correr)\n    return est\n\n\n@router.get(\"/v1/ingestao/{ingestao_id}\", response_model=EstadoIngestao, tags=[\"conhecimento\"])\ndef estado_ingestao(\n    ingestao_id: str,\n    _u: Annotated[Utilizador, Depends(exigir(\"operador\"))],\n    s: Annotated[Any, Depends(servicos)],\n) -> EstadoIngestao:\n    est = s.ingestoes.get(ingestao_id)\n    if est is None:\n        raise ErroProblema(404, \"Ingestão não encontrada\")\n    return est\n\n\n# ================================================================== aprovações\n\n\n@router.get(\"/v1/aprovacoes\", response_model=list[Aprovacao], tags=[\"aprovacoes\"])\ndef listar_aprovacoes(\n    _u: Annotated[Utilizador, Depends(exigir(\"supervisor\"))],\n    s: Annotated[Any, Depends(servicos)],\n    estado: Annotated[str | None, Query(pattern=\"^(pendente|aprovada|recusada)$\")] = \"pendente\",\n) -> list[Aprovacao]:\n    return s.repo.listar_aprovacoes(estado)\n\n\n@router.post(\"/v1/aprovacoes/{aprovacao_id}/decisao\", response_model=ResultadoDecisao, tags=[\"aprovacoes\"])\nasync def decidir_aprovacao(\n    aprovacao_id: str,\n    corpo: Decisao,\n    u: Annotated[Utilizador, Depends(exigir(\"supervisor\"))],\n    s: Annotated[Any, Depends(servicos)],\n) -> ResultadoDecisao:\n    \"\"\"Regista a decisão e retoma o grafo interrompido com `Command(resume=...)`.\"\"\"\n    ap = await run_in_threadpool(s.repo.obter_aprovacao, aprovacao_id)\n    if ap is None:\n        raise ErroProblema(404, \"Aprovação não encontrada\")\n    if ap.estado != \"pendente\":\n        raise ErroProblema(409, \"Aprovação já decidida\", f\"Estado actual: {ap.estado}.\")\n    config = config_de_execucao(ap.conversa_id, ap.cliente_id, s.cfg, revisor=u.sujeito)\n    config[\"callbacks\"] = s.callbacks\n    estado = await s.grafo.ainvoke(\n        Command(resume={\"aprovado\": corpo.aprovado, \"revisor\": u.sujeito, \"nota\": corpo.nota}), config\n    )\n    ap = await run_in_threadpool(s.repo.decidir_aprovacao, aprovacao_id, corpo.aprovado, u.sujeito, corpo.nota)\n    final = next(m for m in reversed(estado[\"messages\"]) if isinstance(m, AIMessage))\n    msg = await run_in_threadpool(\n        s.repo.adicionar_mensagem,\n        ap.conversa_id,\n        \"assistente\",\n        final.text,\n        [],\n        estado.get(\"intencao\"),\n        {\"rota\": \"aprovacao\", \"revisor\": u.sujeito},\n    )\n    await run_in_threadpool(s.repo.mudar_estado_conversa, ap.conversa_id, \"aberta\")\n    return ResultadoDecisao(aprovacao=ap, mensagem=msg)\n\n\n# =================================================================== avaliação\n\n\n@router.post(\"/v1/avaliacoes\", status_code=202, response_model=EstadoAvaliacao, tags=[\"avaliacao\"])\ndef correr_avaliacao(\n    corpo: PedidoAvaliacao,\n    tarefas: BackgroundTasks,\n    _u: Annotated[Utilizador, Depends(exigir(\"operador\"))],\n    s: Annotated[Any, Depends(servicos)],\n) -> EstadoAvaliacao:\n    \"\"\"Corre o conjunto dourado (e/ou o red team) contra um sistema isolado, com os limiares do gate.\"\"\"\n    from balcao.avaliacao.correr import avaliar\n\n    est = EstadoAvaliacao(id=novo_id(\"AV\"), estado=\"pendente\", conjunto=corpo.conjunto, criada_em=datetime.now(UTC))\n    s.repo.guardar_avaliacao(est)\n\n    def correr() -> None:\n        s.repo.guardar_avaliacao(est.model_copy(update={\"estado\": \"a_correr\"}))\n        try:\n            rel = avaliar(s.cfg, conjunto=corpo.conjunto, limite=corpo.limite, indice=s.sistema.indice)\n            s.repo.guardar_avaliacao(\n                est.model_copy(update={\"estado\": \"concluida\", \"metricas\": rel.metricas, \"gate_ok\": rel.gate_ok}),\n                versao_prompt=rel.versao_prompt,\n                modelo=rel.modelo,\n            )\n        except Exception as e:\n            log.exception(\"avaliação %s falhou\", est.id)\n            s.repo.guardar_avaliacao(est.model_copy(update={\"estado\": \"falhou\", \"erro\": type(e).__name__}))\n\n    tarefas.add_task(correr)\n    return est\n\n\n@router.get(\"/v1/avaliacoes/{avaliacao_id}\", response_model=EstadoAvaliacao, tags=[\"avaliacao\"])\ndef ler_avaliacao(\n    avaliacao_id: str,\n    _u: Annotated[Utilizador, Depends(exigir(\"operador\"))],\n    s: Annotated[Any, Depends(servicos)],\n) -> EstadoAvaliacao:\n    av = s.repo.obter_avaliacao(avaliacao_id)\n    if av is None:\n        raise ErroProblema(404, \"Avaliação não encontrada\")\n    return av\n\n\n# ================================================================ operação\n\n\n@router.get(\"/healthz\", response_model=Saude, tags=[\"operacao\"])\ndef saude(s: Annotated[Any, Depends(servicos)]) -> Saude:\n    \"\"\"Vivo: o processo responde. Não toca em dependências (senão o orquestrador mata-o por culpa da BD).\"\"\"\n    return Saude(estado=\"ok\", versao=s.cfg.versao, fornecedor=s.cfg.modelo_fornecedor)\n\n\n@router.get(\n    \"/readyz\",\n    response_model=Saude,\n    tags=[\"operacao\"],\n    responses={503: {\"description\": \"Não está pronto para receber tráfego\"}},\n)\ndef prontidao(s: Annotated[Any, Depends(servicos)], resposta: Response) -> Saude:\n    \"\"\"Pronto: a base de dados responde e o índice tem chunks.\"\"\"\n    try:\n        chunks = s.sistema.indice.contar_chunks()\n    except Exception:\n        chunks = -1\n    detalhes = {\"chunks\": chunks, \"repositorio\": s.repo.pronto()}\n    ok = chunks > 0 and detalhes[\"repositorio\"]\n    if not ok:\n        resposta.status_code = 503\n    return Saude(\n        estado=\"ok\" if ok else \"degradado\", versao=s.cfg.versao, fornecedor=s.cfg.modelo_fornecedor, detalhes=detalhes\n    )\n\n\n@router.get(\"/metrics\", tags=[\"operacao\"], include_in_schema=False)\ndef metricas() -> Response:\n    return Response(generate_latest(), media_type=CONTENT_TYPE_LATEST)\n",
  "src/balcao/observabilidade.py": "\"\"\"Observabilidade: traços OpenTelemetry com as convenções `gen_ai.*` e métricas Prometheus (adr-0025).\n\nTrês perguntas que qualquer incidente faz, e onde a resposta está:\n\n* **Quanto demorou e onde?** — spans `chat {modelo}` e `execute_tool {nome}`\n  com os atributos da semconv GenAI (`gen_ai.operation.name`,\n  `gen_ai.request.model`, `gen_ai.usage.input_tokens`, ...), e os histogramas\n  `balcao_ttft_segundos` e `balcao_resposta_duracao_segundos` (RNF-01).\n* **Quanto custou?** — `balcao_tokens_total` e `balcao_custo_mzn_total` por\n  modelo, calculados com os preços de referência de `didactico.MODELOS` (RNF-02).\n* **O que foi recusado?** — `balcao_recusas_total`, `balcao_ferramentas_total`\n  por resultado e `balcao_injeccao_suspeitas_total` (RI-01, RI-02).\n\nO `CallbackObservabilidade` liga isto ao LangChain sem tocar nas cadeias: é\npassado em `config[\"callbacks\"]` e vê todas as chamadas a modelos do turno.\nOs textos das mensagens *não* vão para os spans (RNF-04): só tamanhos e contagens.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport time\nfrom collections.abc import Iterator\nfrom contextlib import contextmanager\nfrom typing import Any\nfrom uuid import UUID\n\nfrom langchain_core.callbacks import BaseCallbackHandler\nfrom langchain_core.messages import BaseMessage\nfrom langchain_core.outputs import ChatGenerationChunk, GenerationChunk, LLMResult\nfrom opentelemetry import trace\nfrom opentelemetry.sdk.resources import Resource\nfrom opentelemetry.sdk.trace import TracerProvider\nfrom opentelemetry.sdk.trace.export import ConsoleSpanExporter, SimpleSpanProcessor\nfrom opentelemetry.trace import Span, Status, StatusCode\nfrom prometheus_client import Counter, Histogram\n\nfrom balcao import didactico\n\n__all__ = [\n    \"CUSTO_MZN\",\n    \"DURACAO\",\n    \"FERRAMENTAS\",\n    \"INJECCOES\",\n    \"LIMITES\",\n    \"RECUSAS\",\n    \"TOKENS\",\n    \"TTFT\",\n    \"TTFT_MODELO\",\n    \"CallbackObservabilidade\",\n    \"configurar\",\n    \"span_ferramenta\",\n    \"tracer\",\n]\n\n# Baldes pensados para o orçamento: TTFT alvo p95 < 1,5 s; resposta p95 < 5 s.\n_BALDES_TTFT = (0.1, 0.25, 0.5, 0.75, 1.0, 1.5, 2.0, 3.0, 5.0)\n_BALDES_DURACAO = (0.25, 0.5, 1.0, 2.0, 3.0, 5.0, 8.0, 13.0, 21.0)\n\nTTFT = Histogram(\n    \"balcao_ttft_segundos\", \"Tempo até ao primeiro token visível ao cliente\", [\"rota\"], buckets=_BALDES_TTFT\n)\nTTFT_MODELO = Histogram(\n    \"balcao_modelo_ttft_segundos\", \"Tempo até ao primeiro token do modelo\", [\"modelo\"], buckets=_BALDES_TTFT\n)\nDURACAO = Histogram(\n    \"balcao_resposta_duracao_segundos\", \"Duração de um turno completo\", [\"rota\"], buckets=_BALDES_DURACAO\n)\nTOKENS = Counter(\"balcao_tokens_total\", \"Tokens por modelo e tipo\", [\"modelo\", \"tipo\"])\nCUSTO_MZN = Counter(\"balcao_custo_mzn_total\", \"Custo de modelo em meticais\", [\"modelo\"])\nRECUSAS = Counter(\"balcao_recusas_total\", \"Respostas trocadas por recusa\", [\"motivo\"])\nFERRAMENTAS = Counter(\"balcao_ferramentas_total\", \"Chamadas de ferramentas\", [\"ferramenta\", \"resultado\"])\nINJECCOES = Counter(\"balcao_injeccao_suspeitas_total\", \"Mensagens com suspeita de prompt injection\")\nLIMITES = Counter(\"balcao_limite_ferramentas_total\", \"Turnos que esgotaram o orçamento de ferramentas\")\n\ntracer = trace.get_tracer(\"balcao\")\n\n_configurado = False\n\n\ndef configurar(servico: str = \"balcao\", versao: str = \"0.1.0\", consola: bool = False) -> None:\n    \"\"\"Instala o `TracerProvider`. Em produção junta-se um exportador OTLP (Langfuse, Tempo, ...)\n    via `opentelemetry-exporter-otlp`; aqui só a consola, para ver os spans no laboratório.\"\"\"\n    global _configurado\n    if _configurado:\n        return\n    provider = TracerProvider(resource=Resource.create({\"service.name\": servico, \"service.version\": versao}))\n    if consola:\n        provider.add_span_processor(SimpleSpanProcessor(ConsoleSpanExporter()))\n    trace.set_tracer_provider(provider)\n    _configurado = True\n\n\n@contextmanager\ndef span_ferramenta(nome: str, chamada_id: str | None = None) -> Iterator[Span]:\n    \"\"\"Span `execute_tool` da semconv GenAI à volta de uma chamada de ferramenta.\"\"\"\n    with tracer.start_as_current_span(f\"execute_tool {nome}\") as span:\n        span.set_attribute(\"gen_ai.operation.name\", \"execute_tool\")\n        span.set_attribute(\"gen_ai.tool.name\", nome)\n        if chamada_id:\n            span.set_attribute(\"gen_ai.tool.call.id\", chamada_id)\n        yield span\n\n\nclass CallbackObservabilidade(BaseCallbackHandler):\n    \"\"\"Um span `chat` por chamada ao modelo, com tokens, custo e TTFT.\n\n    `escaloes` mapeia o nome do modelo para o escalão de preço (`pequeno`,\n    `medio`, `grande`, `local`) usado no custo em MZN.\n    \"\"\"\n\n    def __init__(self, fornecedor: str, escaloes: dict[str, str] | None = None) -> None:\n        self.fornecedor = fornecedor\n        self.escaloes = escaloes or {}\n        self._spans: dict[UUID, tuple[Span, float, str]] = {}\n        self._primeiro: set[UUID] = set()\n\n    def on_chat_model_start(\n        self, serialized: dict[str, Any], messages: list[list[BaseMessage]], *, run_id: UUID, **kwargs: Any\n    ) -> None:\n        params = kwargs.get(\"invocation_params\") or {}\n        modelo = str(params.get(\"model\") or params.get(\"model_name\") or params.get(\"nome_modelo\") or \"desconhecido\")\n        span = tracer.start_span(f\"chat {modelo}\")\n        span.set_attribute(\"gen_ai.operation.name\", \"chat\")\n        span.set_attribute(\"gen_ai.provider.name\", self.fornecedor)\n        span.set_attribute(\"gen_ai.request.model\", modelo)\n        if \"temperature\" in params:\n            span.set_attribute(\"gen_ai.request.temperature\", float(params[\"temperature\"]))\n        span.set_attribute(\"balcao.mensagens\", sum(len(m) for m in messages))\n        self._spans[run_id] = (span, time.perf_counter(), modelo)\n\n    def on_llm_new_token(\n        self,\n        token: str | list[str | dict[str, Any]],\n        *,\n        chunk: GenerationChunk | ChatGenerationChunk | None = None,\n        run_id: UUID,\n        parent_run_id: UUID | None = None,\n        **kwargs: Any,\n    ) -> None:\n        if run_id in self._spans and run_id not in self._primeiro and token:\n            self._primeiro.add(run_id)\n            _, t0, modelo = self._spans[run_id]\n            TTFT_MODELO.labels(modelo=modelo).observe(time.perf_counter() - t0)\n\n    def on_llm_end(self, response: LLMResult, *, run_id: UUID, **kwargs: Any) -> None:\n        registo = self._spans.pop(run_id, None)\n        self._primeiro.discard(run_id)\n        if registo is None:\n            return\n        span, _, modelo = registo\n        entrada = saida = 0\n        for geracoes in response.generations:\n            for g in geracoes:\n                uso = getattr(getattr(g, \"message\", None), \"usage_metadata\", None) or {}\n                entrada += int(uso.get(\"input_tokens\", 0))\n                saida += int(uso.get(\"output_tokens\", 0))\n        span.set_attribute(\"gen_ai.usage.input_tokens\", entrada)\n        span.set_attribute(\"gen_ai.usage.output_tokens\", saida)\n        span.set_attribute(\"gen_ai.response.model\", modelo)\n        TOKENS.labels(modelo=modelo, tipo=\"entrada\").inc(entrada)\n        TOKENS.labels(modelo=modelo, tipo=\"saida\").inc(saida)\n        custo = didactico.custo_mzn(entrada, saida, self.escaloes.get(modelo, \"medio\"))\n        CUSTO_MZN.labels(modelo=modelo).inc(custo)\n        span.set_attribute(\"balcao.custo_mzn\", custo)\n        span.end()\n\n    def on_llm_error(self, error: BaseException, *, run_id: UUID, **kwargs: Any) -> None:\n        registo = self._spans.pop(run_id, None)\n        self._primeiro.discard(run_id)\n        if registo is None:\n            return\n        span = registo[0]\n        span.set_attribute(\"error.type\", type(error).__name__)\n        span.set_status(Status(StatusCode.ERROR, str(error)[:200]))\n        span.end()\n",
};
